	private static class FuncNameMatchColumn : AbstractProgramBasedDynamicTableColumn<BSimMatchResult, string> {

		/* @Override */
		public string getColumnName() {
			return "Matching Function Name";
		}

		/* @Override */
		public string getValue(BSimMatchResult rowObject, Settings settings, Program p,
				ServiceProvider serviceProvider)
    {
			string name = rowObject.getSimilarFunctionName();
			bool showNamespace = SHOW_NAMESPACE.getValue(settings);
			if (!showNamespace) {
				int lastIndexOf = name.lastIndexOf("::");
				if (lastIndexOf > 0) {
					name = name.substring(lastIndexOf + 2);
				}
			}
			return name;
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 200;
		}

		/* @Override */
		public SettingsDefinition[] getSettingsDefinitions() {
			return SETTINGS_DEFS;
		}
	}

